  ('5bf07f11-a699-5322-993f-0ae0fe8c64fb', '1a6c2b82-f00f-5514-8d02-3ab15b7f52cf', 'A', 'Measles', true, 0),
  ('343d4aa2-7ce9-5818-8c26-deafe32747d6', '1a6c2b82-f00f-5514-8d02-3ab15b7f52cf', 'B', 'Influenza in a healthy adult', false, 1),
  ('72658a78-173b-5fc2-976f-244fe341d8d5', '1a6c2b82-f00f-5514-8d02-3ab15b7f52cf', 'C', 'Chlamydia', false, 2),
  ('9ec7e121-b3d2-5bca-9b3b-396303ff29c0', '1a6c2b82-f00f-5514-8d02-3ab15b7f52cf', 'D', 'Genital herpes', false, 3),
  ('f0f7dbfb-8d71-58a7-9020-8f41cde12963', '1a6c2b82-f00f-5514-8d02-3ab15b7f52cf', 'E', 'HIV infection', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('74cbbe3b-16da-530c-b4d6-d870c3bc2b86', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 28 year old woman has a malar rash, painful small-joint arthritis, mouth ulcers, and proteinuria of 1.2 g/24h. Her ANA is strongly positive. Which test is MOST useful to monitor disease activity?', 'In SLE, anti-dsDNA titres rise and complement (C3, C4) falls during active disease, especially lupus nephritis. Anti-Smith is highly specific but does not track activity. Proteinuria over 0.5 g/day needs a renal biopsy to classify lupus nephritis. All patients should take hydroxychloroquine unless contraindicated, with annual eye screening.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
