  ('cc6b334d-f2fc-5345-be1a-cc02891b56fb', 'a2272738-d37a-5202-b404-54c1deb59205', 'A', 'Keloid scar', true, 0),
  ('3632171a-88a2-5625-91a3-241edbbe62b2', 'a2272738-d37a-5202-b404-54c1deb59205', 'B', 'Basal cell carcinoma', false, 1),
  ('52d9c556-f8ca-522c-adc6-a851a5020a8b', 'a2272738-d37a-5202-b404-54c1deb59205', 'C', 'Dermatofibroma', false, 2),
  ('705343c0-e87e-50f7-a865-2835ec38ca6c', 'a2272738-d37a-5202-b404-54c1deb59205', 'D', 'Hypertrophic scar', false, 3),
  ('4dcecd5c-cf1c-5acb-a4c6-f3c35b0c259f', 'a2272738-d37a-5202-b404-54c1deb59205', 'E', 'Epidermoid cyst', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('be610631-7bda-5265-a4e7-946297c39c41', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'An adult has full-thickness and partial-thickness burns involving the entire front of the trunk and the whole of the left arm. Using the Wallace rule of nines, what percentage of total body surface area is burned?', 'Rule of nines in adults: head 9%, each arm 9%, front of trunk 18%, back of trunk 18%, each leg 18%, perineum 1%. Here front of trunk (18%) + one arm (9%) = 27%. Simple erythema is excluded. The Parkland formula (4 mL x kg x %TBSA) estimates the crystalloid needed over the first 24 hours, half in the first 8 hours from the time of the burn. Adults with burns over 15% (10% in children) need formal fluid resuscitation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('49762dc3-55bc-5191-846a-ab281a4e855d', 'be610631-7bda-5265-a4e7-946297c39c41', 'A', '9%', false, 0),
  ('43a215cb-dad4-5b99-9b47-b75f887a733a', 'be610631-7bda-5265-a4e7-946297c39c41', 'B', '18%', false, 1),
  ('33520672-7d19-5a4d-a90a-bbb8e161ad81', 'be610631-7bda-5265-a4e7-946297c39c41', 'C', '27%', true, 2),
  ('e61f8167-ed32-5024-b7cc-2e0e2976b371', 'be610631-7bda-5265-a4e7-946297c39c41', 'D', '36%', false, 3),
  ('52cffdc0-ea9c-54ce-88fd-3033229faa7e', 'be610631-7bda-5265-a4e7-946297c39c41', 'E', '45%', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b2a65560-54a0-5530-b6a1-0e160a19ecb2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 55 year old woman with osteoarthritis of the knee has a smooth, fluctuant swelling at the back of her knee. It is more prominent when standing. She then gets sudden calf pain and swelling. Which condition MUST be excluded?', 'A popliteal (Baker''s) cyst comes with knee pathology such as OA and RA. Rupture can cause sudden calf pain and swelling that mimics DVT (pseudothrombophlebitis), and may cause a crescent-shaped bruise at the ankle. DVT must be excluded with duplex ultrasound, which also shows the cyst. Treat the underlying knee pathology.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('fcaf3ff9-6b8f-59bf-ade1-d36d4ce77c8f', 'b2a65560-54a0-5530-b6a1-0e160a19ecb2', 'A', 'Septic arthritis of the ankle', false, 0),
  ('eaf0f7bc-c161-51e7-a641-dd2deaa63953', 'b2a65560-54a0-5530-b6a1-0e160a19ecb2', 'B', 'Achilles tendon rupture', false, 1),
  ('1e0ad49f-93b9-52bc-8f1f-ad862bad2846', 'b2a65560-54a0-5530-b6a1-0e160a19ecb2', 'C', 'Peripheral arterial disease', false, 2),
  ('2e28dc8c-4cc8-5999-ad48-fd41758d7233', 'b2a65560-54a0-5530-b6a1-0e160a19ecb2', 'D', 'Deep vein thrombosis (with a ruptured Baker''s cyst as the alternative)', true, 3),
  ('9f8f7088-984c-5490-80f7-06b0b6033c36', 'b2a65560-54a0-5530-b6a1-0e160a19ecb2', 'E', 'Gout', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a50e4c1f-1882-57b7-b7f6-7bda1e99651c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 40 year old man jammed the tip of his middle finger while catching a ball. He now cannot actively extend the distal interphalangeal (DIP) joint, which droops in flexion, although it can be passively straightened. What is the SINGLE most appropriate management?', 'Mallet finger is a disruption of the terminal extensor tendon at the DIP joint (sometimes with an avulsion fracture). Most cases are treated with a mallet splint, keeping the DIP joint continuously extended for 6-8 weeks (any flexion restarts the clock), then night splinting. Large fracture fragments with joint subluxation may need surgery. An untreated mallet can lead to a swan-neck deformity.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ce88c83e-a5d4-50ac-ade1-3d4394e5324d', 'a50e4c1f-1882-57b7-b7f6-7bda1e99651c', 'A', 'No treatment', false, 0),
  ('7990492e-f847-59b8-9b45-4b3e0ac9c38c', 'a50e4c1f-1882-57b7-b7f6-7bda1e99651c', 'B', 'Splint the DIP joint in extension (mallet splint) continuously for 6-8 weeks, with X-ray to check for a bony fragment', true, 1),
  ('efcaaa78-0759-5146-b3f7-2156458c16b7', 'a50e4c1f-1882-57b7-b7f6-7bda1e99651c', 'C', 'Immediate surgical repair in all cases', false, 2),
  ('09883284-7451-5477-b64c-cee4600b4d73', 'a50e4c1f-1882-57b7-b7f6-7bda1e99651c', 'D', 'Buddy strapping for 1 week', false, 3),
  ('34587f33-21b6-53b3-ab9a-c0b8277d0556', 'a50e4c1f-1882-57b7-b7f6-7bda1e99651c', 'E', 'Splint in flexion', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('92df0836-1c72-5789-9048-8208a8cf7c3c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 9 year old boy fell onto his outstretched arm. X-ray shows a fracture of the proximal third of the ulna. What associated injury MUST be looked for?', 'A Monteggia injury is a proximal ulnar fracture with radial head dislocation. A Galeazzi injury is a distal radial shaft fracture with distal radioulnar joint dislocation (''MUGR'': Monteggia = Ulna fracture; Galeazzi = Radius fracture). Always X-ray the joints above and below a forearm fracture. A radiocapitellar line that does not pass through the capitellum shows radial head dislocation. The posterior interosseous nerve may be injured.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6e0e99a2-0520-5cdb-9f0b-960dec338a77', '92df0836-1c72-5789-9048-8208a8cf7c3c', 'A', 'Scaphoid fracture', false, 0),
  ('b57b106e-a555-59d7-bf21-f34e0eda097b', '92df0836-1c72-5789-9048-8208a8cf7c3c', 'B', 'Perilunate dislocation', false, 1),
  ('9fd57bff-7095-5b1d-997e-3eb40bf6822c', '92df0836-1c72-5789-9048-8208a8cf7c3c', 'C', 'Distal radioulnar joint dislocation', false, 2),
  ('abe868f0-5cad-5b5e-990f-7eca7cf0fd0d', '92df0836-1c72-5789-9048-8208a8cf7c3c', 'D', 'Dislocation of the radial head (Monteggia fracture-dislocation)', true, 3),
  ('74cfd402-ef13-5097-b0b8-18161b944a08', '92df0836-1c72-5789-9048-8208a8cf7c3c', 'E', 'Supracondylar fracture of the humerus', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('40840b49-13cf-5a21-aa3f-bac5bd05bb9e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 28 year old woman twisted her ankle playing netball. She can bear weight for 4 steps. There is tenderness over the anterior talofibular ligament, but no bony tenderness at the posterior edge or tip of either malleolus, base of the fifth metatarsal or navicular. What is the SINGLE most appropriate management?', 'The Ottawa ankle rules recommend an ankle X-ray only if there is malleolar zone pain plus either bony tenderness at the posterior edge or tip of the lateral or medial malleolus, or inability to bear weight for 4 steps both immediately and in the Emergency Department. A foot X-ray is indicated for midfoot pain with tenderness at the base of the fifth metatarsal or the navicular, or inability to bear weight. Otherwise, manage as a sprain.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2974f952-7a59-5cd3-9e59-61838ac373eb', '40840b49-13cf-5a21-aa3f-bac5bd05bb9e', 'A', 'X-ray of the ankle and foot', false, 0),
  ('6b4d4dc8-b0a5-5fa1-9262-af42c3b588df', '40840b49-13cf-5a21-aa3f-bac5bd05bb9e', 'B', 'Orthopaedic referral', false, 1),
  ('175ce3f8-7885-5144-9bac-f92a5eac0f33', '40840b49-13cf-5a21-aa3f-bac5bd05bb9e', 'C', 'MRI of the ankle', false, 2),
  ('a74ec00d-f7c0-59c6-a4fb-e3eaf17a4b52', '40840b49-13cf-5a21-aa3f-bac5bd05bb9e', 'D', 'No X-ray needed; manage as an ankle sprain with rest, ice, compression, elevation and early mobilisation', true, 3),
  ('5e682082-a78d-50ae-869f-cec7d4d38bd1', '40840b49-13cf-5a21-aa3f-bac5bd05bb9e', 'E', 'Below-knee cast for 6 weeks', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f33deaf3-9754-5a66-8369-0bc42cd773b4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 15 year old gymnast has had low back pain for 3 months, worse on extension. Lateral lumbar X-ray shows anterior slippage of L5 on S1 with a defect in the pars interarticularis. What is the SINGLE most likely diagnosis?', 'Spondylolysis is a stress fracture of the pars interarticularis, common in adolescents in hyperextension sports (gymnastics, cricket fast bowling). Bilateral defects allow forward slippage (isthmic spondylolisthesis), usually L5 on S1. Oblique views show the ''Scottie dog collar''. Most cases are managed conservatively (rest, physiotherapy). High-grade or progressive slips, or neurological symptoms, need surgery. Degenerative spondylolisthesis affects older adults at L4/5.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('15f58652-0131-5cf9-a3e5-b9b88b2d87f9', 'f33deaf3-9754-5a66-8369-0bc42cd773b4', 'A', 'Ankylosing spondylitis', false, 0),
  ('54241ed3-1434-5c22-bbcf-27baf0899192', 'f33deaf3-9754-5a66-8369-0bc42cd773b4', 'B', 'Isthmic spondylolisthesis (from spondylolysis)', true, 1),
  ('e2ac7ea4-9a27-5805-babb-199035d537e7', 'f33deaf3-9754-5a66-8369-0bc42cd773b4', 'C', 'Degenerative spondylolisthesis', false, 2),
  ('42e31da3-f288-5ebe-b7d9-b8a044354ede', 'f33deaf3-9754-5a66-8369-0bc42cd773b4', 'D', 'Scheuermann''s disease', false, 3),
  ('ac39b3f4-c32d-5327-856e-6421b572c459', 'f33deaf3-9754-5a66-8369-0bc42cd773b4', 'E', 'Lumbar disc prolapse', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9e657c5c-6655-5da5-a521-17dc272f5cc9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'The parents of a newborn ask how to reduce the risk of sudden infant death syndrome (SIDS). Which advice is CORRECT?', 'Safe sleep advice from the Lullaby Trust and NHS: back to sleep, feet-to-foot, no pillows, duvets or bumpers, avoid overheating, a smoke-free environment, room-sharing (in a separate cot) for the first 6 months, and breastfeeding if possible. Never sleep with a baby on a sofa or armchair, and avoid bed-sharing after alcohol, drugs, smoking, or with a premature or low birthweight baby. A dummy at sleep time may reduce risk.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('94abc356-382e-5641-b11f-f1b3ddacb753', '9e657c5c-6655-5da5-a521-17dc272f5cc9', 'A', 'Put the baby to sleep on their front', false, 0),
  ('cf3b628c-b380-5a4f-aa50-bf9b1e125e96', '9e657c5c-6655-5da5-a521-17dc272f5cc9', 'B', 'Put the baby to sleep on their back, in their own cot in the parents'' room for the first 6 months, in a smoke-free home, with feet to the foot of the cot', true, 1),
  ('e12ab69b-0e73-5f16-bdf4-288dfe3ab6ef', '9e657c5c-6655-5da5-a521-17dc272f5cc9', 'C', 'Use pillows and duvets to keep the baby warm', false, 2),
  ('74ef8c2c-36b7-5055-a6ba-8ef215702ed5', '9e657c5c-6655-5da5-a521-17dc272f5cc9', 'D', 'Bed-share after drinking alcohol is safe if careful', false, 3),
  ('8ab8a6f1-64ac-5f81-85c2-eca185b8ba21', '9e657c5c-6655-5da5-a521-17dc272f5cc9', 'E', 'Sleep on a sofa with the baby to settle them', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e74ff479-779b-5616-aaac-e48026429b3e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 40 year old farm worker is brought in after spraying pesticides. He has pinpoint pupils, profuse salivation, lacrimation, sweating, diarrhoea, bradycardia, wheeze and muscle fasciculations. What is the SINGLE most appropriate treatment?', 'Organophosphate poisoning inhibits acetylcholinesterase and causes a cholinergic crisis. Muscarinic features are summarised by DUMBELS (diarrhoea, urination, miosis, bradycardia/bronchorrhoea/bronchospasm, emesis, lacrimation, salivation/sweating). Nicotinic features are fasciculations and weakness. Staff should wear PPE and decontaminate the patient. Give IV atropine in doubling doses until the chest is clear of secretions. Pralidoxime (an oxime) may reactivate the enzyme. Watch for respiratory failure.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('045ae8ef-6cf1-593f-87d9-5798494a77d3', 'e74ff479-779b-5616-aaac-e48026429b3e', 'A', 'IV physostigmine', false, 0),
  ('d3a2fd2e-1938-5e1e-ab4a-e08762c2d74b', 'e74ff479-779b-5616-aaac-e48026429b3e', 'B', 'IV atropine, titrated to dry chest secretions (with pralidoxime considered), after decontamination', true, 1),
  ('b7f46860-cde4-527d-b77a-ff0a581aa4dd', 'e74ff479-779b-5616-aaac-e48026429b3e', 'C', 'IV naloxone', false, 2),
  ('f1e22456-aeaf-58dc-b818-76e22a2ac5a3', 'e74ff479-779b-5616-aaac-e48026429b3e', 'D', 'IV flumazenil', false, 3),
  ('725d3c7d-7984-5575-87b5-d9d61d878fd9', 'e74ff479-779b-5616-aaac-e48026429b3e', 'E', 'IV adrenaline', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0c9c7a1b-a850-56c7-9b73-346d3ba36cc3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 52 year old woman took a large overdose of propranolol 2 hours ago. Her HR is 38 bpm and BP is 70/40 mmHg despite IV atropine and fluids. What is the SINGLE most appropriate specific treatment?', 'Beta-blocker overdose causes bradycardia, hypotension, hypoglycaemia and (with propranolol) seizures and QRS widening. After atropine, glucagon raises cardiac output by stimulating adenylate cyclase independently of beta-receptors. High-dose insulin euglycaemic therapy, inotropes or vasopressors, and pacing are also used. Lipid emulsion is considered for propranolol (which is lipophilic). Seek TOXBASE or NPIS advice.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('24e1dadf-d028-55b0-9c24-20a24b49518f', '0c9c7a1b-a850-56c7-9b73-346d3ba36cc3', 'A', 'IV flumazenil', false, 0),
  ('cec9e946-a480-5972-a358-ffc455c7210c', '0c9c7a1b-a850-56c7-9b73-346d3ba36cc3', 'B', 'IV acetylcysteine', false, 1),
  ('be6b9f24-2a35-568c-928e-b451bd91f389', '0c9c7a1b-a850-56c7-9b73-346d3ba36cc3', 'C', 'IV naloxone', false, 2),
  ('bac05eeb-941c-51b8-9e58-da0c807d448b', '0c9c7a1b-a850-56c7-9b73-346d3ba36cc3', 'D', 'IV glucagon (and high-dose insulin euglycaemic therapy, with expert advice)', true, 3),
  ('fe54e239-6c87-53f6-9b0b-5c45b0d4f5c6', '0c9c7a1b-a850-56c7-9b73-346d3ba36cc3', 'E', 'IV digoxin-specific antibody fragments', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('126c7a82-314d-5841-97cb-d7e3a9213d5b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 35 year old man was bitten on his ankle by a snake while walking on heathland in southern England 1 hour ago. He now has spreading swelling up to his knee, vomiting and a BP of 85/50 mmHg. What is the SINGLE most appropriate specific treatment?', 'The adder (Vipera berus) is the UK''s only native venomous snake. Most bites cause only local swelling. Antivenom (ViperaTAb) is indicated for systemic envenoming (hypotension, vomiting, ECG changes, leucocytosis, coagulopathy) or significant spreading swelling (beyond the wrist after a hand bite, or the ankle after a foot bite, within 4 hours). Immobilise the limb. Do not use tourniquets, incision or suction. Observe all bites for at least 24 hours if there are any signs, and check tetanus status.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('521609b4-7c21-541c-8a16-418b614f5f3f', '126c7a82-314d-5841-97cb-d7e3a9213d5b', 'A', 'European viper antivenom (adder) given IV, with supportive care', true, 0),
  ('aa4933e9-1b05-591e-a081-924a782d11bb', '126c7a82-314d-5841-97cb-d7e3a9213d5b', 'B', 'Apply a tourniquet above the bite', false, 1),
  ('15166ac5-1226-5590-aa96-a71bdd25b8dd', '126c7a82-314d-5841-97cb-d7e3a9213d5b', 'C', 'Observe for 2 hours and discharge', false, 2),
  ('32705c06-6862-57dc-882c-71efeb9400e8', '126c7a82-314d-5841-97cb-d7e3a9213d5b', 'D', 'IV antibiotics only', false, 3),
  ('070dec94-0d4f-5ba9-97a9-c08f336b6da1', '126c7a82-314d-5841-97cb-d7e3a9213d5b', 'E', 'Incise and suck the wound', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e9a736ff-ad9a-5d18-8778-1312e46e8980', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 28 year old woman who is 30 weeks pregnant returned from South Asia 5 weeks ago. She has jaundice, malaise and a very high ALT. Hepatitis A, B and C serology is negative. Which virus is MOST likely, and why is it important?', 'Hepatitis E is spread by the faecal-oral route (genotypes 1/2 in Asia and Africa through water; genotype 3 in the UK through undercooked pork). It is usually self-limiting, but genotypes 1/2 in pregnancy cause fulminant hepatitis with high maternal mortality. In immunosuppressed people, genotype 3 can become chronic. Diagnosis is by HEV IgM or PCR. Hepatitis D needs hepatitis B co-infection.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('87896040-51b2-55f6-a13c-ddab8d3b5e5c', 'e9a736ff-ad9a-5d18-8778-1312e46e8980', 'A', 'Hepatitis E — it can cause fulminant hepatic failure in pregnancy (especially the third trimester)', true, 0),
  ('fe391b50-ec4c-5d09-8bd2-c34a532c3910', 'e9a736ff-ad9a-5d18-8778-1312e46e8980', 'B', 'Hepatitis D — only infects people with hepatitis C', false, 1),
  ('293ddad8-a1d0-5f6c-8326-0ad13cbabb86', 'e9a736ff-ad9a-5d18-8778-1312e46e8980', 'C', 'CMV — always causes fatal hepatitis', false, 2),
  ('66d132f6-602c-556f-aebe-610e2e33eec7', 'e9a736ff-ad9a-5d18-8778-1312e46e8980', 'D', 'Hepatitis A — it is never self-limiting', false, 3),
  ('56720628-ecc8-5ff6-9b69-6427754c2bd7', 'e9a736ff-ad9a-5d18-8778-1312e46e8980', 'E', 'Hepatitis G — common cause of liver failure', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6cc5dd08-9fbc-52bb-8e65-8404f0f82cbe', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 50 year old man is crushed by a car. His right chest wall moves inward on inspiration and outward on expiration. He is in severe pain and his SpO2 is 89% on high-flow oxygen. What is the SINGLE most likely diagnosis?', 'Flail chest happens when 2 or more adjacent ribs are each fractured in 2 or more places, creating a free segment that moves paradoxically. Hypoxia is mainly caused by the underlying pulmonary contusion. Management: oxygen, excellent analgesia (epidural or regional blocks), physiotherapy, careful fluid management, and ventilation if respiratory failure develops. Surgical rib fixation is increasingly used.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4c6f4b3c-84d4-57ef-99d7-5848f7b8e2e2', '6cc5dd08-9fbc-52bb-8e65-8404f0f82cbe', 'A', 'Massive haemothorax', false, 0),
  ('20eb9956-9998-5dfe-b863-91e597554497', '6cc5dd08-9fbc-52bb-8e65-8404f0f82cbe', 'B', 'Diaphragmatic rupture', false, 1),
  ('4ec2ec36-0bd2-5d51-ba9d-14a1bb3de031', '6cc5dd08-9fbc-52bb-8e65-8404f0f82cbe', 'C', 'Simple rib fracture', false, 2),
  ('9f573783-1d50-5494-b2ca-425d01c66aee', '6cc5dd08-9fbc-52bb-8e65-8404f0f82cbe', 'D', 'Flail chest', true, 3),
  ('736e842a-3544-58fc-9cff-f95ef31c644f', '6cc5dd08-9fbc-52bb-8e65-8404f0f82cbe', 'E', 'Cardiac tamponade', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a29f8b0a-c761-5c60-9623-8a2d68105ccd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 30 year old woman has fatigue and breathlessness. On auscultation there is an ejection systolic murmur in the pulmonary area with fixed splitting of the second heart sound that does not vary with respiration. ECG shows right bundle branch block with right axis deviation. What is the SINGLE most likely diagnosis?', 'An ASD causes a left-to-right shunt and increased flow across the pulmonary valve (the flow murmur). Fixed splitting of S2 is characteristic. Secundum ASD gives RBBB with right axis deviation, and primum ASD gives left axis deviation. Complications include atrial arrhythmias, paradoxical emboli, pulmonary hypertension and Eisenmenger syndrome. Significant defects are closed (often percutaneously).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('fa9b0973-5487-547d-afe3-1d964e411447', 'a29f8b0a-c761-5c60-9623-8a2d68105ccd', 'A', 'Ventricular septal defect', false, 0),
  ('13e8d752-ea24-5cca-abaa-acffa9e34caf', 'a29f8b0a-c761-5c60-9623-8a2d68105ccd', 'B', 'Ostium secundum atrial septal defect', true, 1),
  ('216c920c-2680-552e-bb22-b029b6707cfe', 'a29f8b0a-c761-5c60-9623-8a2d68105ccd', 'C', 'Mitral stenosis', false, 2),
  ('aa548f9e-a626-5c5a-9308-e4601831dccb', 'a29f8b0a-c761-5c60-9623-8a2d68105ccd', 'D', 'Patent ductus arteriosus', false, 3),
  ('f29b98ab-1a99-525e-aa06-bf2f62613fa2', 'a29f8b0a-c761-5c60-9623-8a2d68105ccd', 'E', 'Coarctation of the aorta', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d1040e3a-0c96-58bc-a748-3f9a39acecb0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 35 year old man who smokes 30 cigarettes a day has painful ulcers on his fingertips, rest pain in his toes and migratory superficial thrombophlebitis. He has no diabetes or hyperlipidaemia. What is the SINGLE most likely diagnosis?', 'Buerger''s disease is a non-atherosclerotic inflammatory vasculitis of small and medium arteries and veins in young male heavy smokers. It causes distal ischaemia (digital ulcers and gangrene), claudication of the feet, Raynaud''s and superficial thrombophlebitis. Complete smoking cessation is the only effective treatment, and amputation is common if smoking continues. Angiography shows ''corkscrew'' collaterals.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c5ad2c58-8fb1-5bf2-a1f8-fd16d641e037', 'd1040e3a-0c96-58bc-a748-3f9a39acecb0', 'A', 'Systemic sclerosis', false, 0),
  ('7ac45192-76a5-5ea5-83b8-9ed02028909a', 'd1040e3a-0c96-58bc-a748-3f9a39acecb0', 'B', 'Raynaud''s disease', false, 1),
  ('5e686eaa-405c-542b-af97-fe906b7b94b5', 'd1040e3a-0c96-58bc-a748-3f9a39acecb0', 'C', 'Takayasu arteritis', false, 2),
  ('cdfef5da-aec8-51d2-8d0b-ef5e542ea2cd', 'd1040e3a-0c96-58bc-a748-3f9a39acecb0', 'D', 'Atherosclerotic peripheral arterial disease', false, 3),
  ('50e71b35-d233-5f37-90fe-ba5d97ca588e', 'd1040e3a-0c96-58bc-a748-3f9a39acecb0', 'E', 'Thromboangiitis obliterans (Buerger''s disease)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('cf9dad6b-c708-5e27-a8e2-74d8637e94f8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 62 year old woman has a platelet count of 980 x10^9/L on two occasions. Iron studies, CRP and the blood film are otherwise unremarkable apart from large platelets. She has had burning pain and redness in her fingers. Which mutation is MOST likely to be found?', 'Essential thrombocythaemia is a myeloproliferative neoplasm with persistent thrombocytosis. JAK2 is mutated in about 55%, CALR in about 25% and MPL in about 5%. Exclude reactive causes (iron deficiency, infection, malignancy, splenectomy) and CML (BCR-ABL1). Erythromelalgia (burning red extremities) responds to aspirin. High-risk patients (over 60, previous thrombosis) need cytoreduction (hydroxycarbamide).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0feba7c9-29e5-5c47-9a53-8594c450cf4e', 'cf9dad6b-c708-5e27-a8e2-74d8637e94f8', 'A', 'BCR-ABL1', false, 0),
  ('19e439c8-b592-5cd9-8a5f-a13e7575a723', 'cf9dad6b-c708-5e27-a8e2-74d8637e94f8', 'B', 'JAK2 V617F (or CALR/MPL)', true, 1),
  ('43b8f130-90fc-5c48-9993-aa7617bd259d', 'cf9dad6b-c708-5e27-a8e2-74d8637e94f8', 'C', 'FLT3', false, 2),
  ('39615613-e749-5f64-be89-42ab6b0dee12', 'cf9dad6b-c708-5e27-a8e2-74d8637e94f8', 'D', 'PML-RARA', false, 3),
  ('3ab596c8-a947-52f8-a7b3-b26bde1c93f7', 'cf9dad6b-c708-5e27-a8e2-74d8637e94f8', 'E', 'BRAF V600E', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('70b056f9-7c1d-573e-b62d-31f6327a3318', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 9 year old boy from Malawi has a rapidly growing jaw mass. Biopsy shows sheets of medium-sized lymphocytes with a ''starry sky'' appearance. Which genetic abnormality is MOST characteristic?', 'Burkitt lymphoma is a highly aggressive B-cell NHL with MYC translocation, usually t(8;14). The endemic form (Africa, associated with EBV and malaria) affects the jaw. The sporadic form often presents with an abdominal mass, and it is also associated with HIV. Histology shows a ''starry sky'' (macrophages among sheets of tumour cells). It responds well to intensive chemotherapy but has a high risk of tumour lysis syndrome. t(14;18) is follicular lymphoma and t(11;14) is mantle cell lymphoma.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2e6918fe-e1cb-5f12-bf25-1bf3fe865c71', '70b056f9-7c1d-573e-b62d-31f6327a3318', 'A', 't(15;17) PML-RARA', false, 0),
  ('04cff8e9-9706-581c-9df9-de3a6fc8ea4b', '70b056f9-7c1d-573e-b62d-31f6327a3318', 'B', 't(14;18) BCL2', false, 1),
  ('0bd31762-b93f-52aa-9b04-5a4a2fe9d8bc', '70b056f9-7c1d-573e-b62d-31f6327a3318', 'C', 't(9;22) BCR-ABL1', false, 2),
  ('7aa37ecc-aa19-5884-92d6-e3a4e5c0fca8', '70b056f9-7c1d-573e-b62d-31f6327a3318', 'D', 't(11;14) cyclin D1', false, 3),
  ('77844cfd-b038-5bc3-b632-08ebb1da0ee0', '70b056f9-7c1d-573e-b62d-31f6327a3318', 'E', 't(8;14) translocation involving MYC', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('14e0d2a3-b49e-56ee-bef2-9b6443e1e963', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 70 year old man has fatigue, blurred vision, headaches and nosebleeds. He has lymphadenopathy and hepatosplenomegaly. Serum protein electrophoresis shows a large IgM paraprotein, and fundoscopy shows dilated retinal veins and haemorrhages. What is the SINGLE most likely diagnosis?', 'Waldenström''s macroglobulinaemia (lymphoplasmacytic lymphoma, with MYD88 L265P mutation in about 90%) produces IgM paraprotein, causing hyperviscosity syndrome (visual disturbance, headache, bleeding, retinal ''sausage'' veins). There is lymphadenopathy and organomegaly, but usually no lytic bone lesions (unlike myeloma). Symptomatic hyperviscosity needs urgent plasma exchange, then chemoimmunotherapy (such as rituximab-based) or BTK inhibitors.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cbfaed6d-e5e5-5f63-a8bc-9c74aa9d4dbb', '14e0d2a3-b49e-56ee-bef2-9b6443e1e963', 'A', 'MGUS', false, 0),
  ('12186a2b-8fb1-5c5e-b765-721eb07fb559', '14e0d2a3-b49e-56ee-bef2-9b6443e1e963', 'B', 'Chronic lymphocytic leukaemia', false, 1),
  ('0a350e82-003b-59a8-bd65-097acaba6333', '14e0d2a3-b49e-56ee-bef2-9b6443e1e963', 'C', 'Hodgkin lymphoma', false, 2),
  ('c2f66dac-99c7-515f-af27-ef816a013c8e', '14e0d2a3-b49e-56ee-bef2-9b6443e1e963', 'D', 'Multiple myeloma', false, 3),
  ('a81cb426-c630-5978-87f9-c1f0ac00fe02', '14e0d2a3-b49e-56ee-bef2-9b6443e1e963', 'E', 'Waldenström''s macroglobulinaemia', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a0425657-34b7-5a90-8172-268e0f4dbe82', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 55 year old man with diabetes has a crush injury to his leg. Twenty-four hours later the wound is extremely painful, with brown discharge, crepitus in the tissues and rapidly spreading discolouration. He is hypotensive. What is the SINGLE most likely causative organism?', 'Gas gangrene (clostridial myonecrosis) follows contaminated traumatic wounds. It causes severe pain out of proportion to the signs, crepitus (gas), ''dishwater'' discharge, rapid spread and toxic shock. X-ray or CT shows gas in the tissues. Treatment is emergency surgical debridement (possibly amputation), high-dose IV benzylpenicillin plus clindamycin, and supportive care. Hyperbaric oxygen is sometimes used.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9d402501-3f2b-5875-941b-7cf1ed134e7e', 'a0425657-34b7-5a90-8172-268e0f4dbe82', 'A', 'Clostridium perfringens (gas gangrene)', true, 0),
  ('9f3ff76a-3364-5437-9f07-1d04e08b311e', 'a0425657-34b7-5a90-8172-268e0f4dbe82', 'B', 'Streptococcus pneumoniae', false, 1),
  ('246c0a91-30aa-5331-9dc0-915c037ddd24', 'a0425657-34b7-5a90-8172-268e0f4dbe82', 'C', 'Pseudomonas aeruginosa', false, 2),
  ('80ede628-a2f6-5b9c-9d2c-8f525204b94a', 'a0425657-34b7-5a90-8172-268e0f4dbe82', 'D', 'Escherichia coli', false, 3),
  ('db3f80b7-4139-5cf7-b68c-3d27abc3ad3e', 'a0425657-34b7-5a90-8172-268e0f4dbe82', 'E', 'Staphylococcus aureus', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0c6b2d9d-16bd-5fdf-b8f9-5eb147ce5545', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 26 year old man has had intense itching in his pubic hair for 2 weeks. On examination there are small grey-brown ''specks'' attached to the hairs and tiny blue macules on the lower abdomen. What is the SINGLE most appropriate management?', 'Pubic lice (Phthirus pubis, ''crabs'') are mainly sexually transmitted. Lice and eggs attach to pubic, axillary, chest hair and even eyelashes. Maculae caeruleae are blue-grey macules from bites. Treat with permethrin or malathion applied to all hairy areas and repeated after 7 days. Treat sexual partners from the past 3 months. Wash bedding at 50°C or above. Screen for other STIs.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a5fc7ea6-dc03-58f6-a5ed-3479a9a2db05', '0c6b2d9d-16bd-5fdf-b8f9-5eb147ce5545', 'A', 'Topical permethrin 5% or malathion 0.5% (repeat after 7 days), treat partners, and screen for other STIs', true, 0),
  ('1ab606fa-74fe-5885-bbb9-d9685d24d64b', '0c6b2d9d-16bd-5fdf-b8f9-5eb147ce5545', 'B', 'Oral aciclovir', false, 1),
  ('265f52f2-5a55-5597-b772-984130cbcca2', '0c6b2d9d-16bd-5fdf-b8f9-5eb147ce5545', 'C', 'Topical hydrocortisone', false, 2),
  ('5a7787d9-4538-586c-b5fc-f1a949b8c310', '0c6b2d9d-16bd-5fdf-b8f9-5eb147ce5545', 'D', 'Shave the area as the only treatment', false, 3),
  ('bd5a028c-68bd-579e-b41b-35adec9d9872', '0c6b2d9d-16bd-5fdf-b8f9-5eb147ce5545', 'E', 'Oral fluconazole', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5cd21e55-7b6a-5e81-a4f4-4c5d8a80dfda', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 68 year old man with severe COPD has worsening ankle oedema, a raised JVP and a loud P2. His SpO2 at rest is 86% on air. ECG shows right axis deviation and P pulmonale. What is the SINGLE most likely diagnosis?', 'Cor pulmonale is right ventricular failure caused by pulmonary hypertension from chronic lung disease (COPD, ILD, OSA) through hypoxic pulmonary vasoconstriction. Signs include a raised JVP, peripheral oedema, a loud P2, a parasternal heave and tricuspid regurgitation. Treatment is a loop diuretic for oedema, long-term oxygen therapy if criteria are met (PaO2 under 7.3 kPa, or under 8 with cor pulmonale), and treating the underlying lung disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('dedd6176-302b-5b45-8b01-467b9e4aa995', '5cd21e55-7b6a-5e81-a4f4-4c5d8a80dfda', 'A', 'Constrictive pericarditis', false, 0),
  ('525928fe-878d-53d5-abbf-c05766b46290', '5cd21e55-7b6a-5e81-a4f4-4c5d8a80dfda', 'B', 'Nephrotic syndrome', false, 1),
  ('8dead404-2ae4-5af6-9d3f-fc721e9fe86f', '5cd21e55-7b6a-5e81-a4f4-4c5d8a80dfda', 'C', 'Left ventricular failure', false, 2),
  ('7714c2e3-fa75-53f2-8f16-2b429d08d657', '5cd21e55-7b6a-5e81-a4f4-4c5d8a80dfda', 'D', 'Cor pulmonale (right heart failure secondary to lung disease)', true, 3),
  ('9f354112-c58c-5be9-bfe4-e19282609747', '5cd21e55-7b6a-5e81-a4f4-4c5d8a80dfda', 'E', 'Cirrhosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b0617719-e263-5d6a-8503-978ba55b2e15', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 60 year old man has severe pain in his right ear, followed by vesicles in his ear canal and on his pinna, and a right-sided facial weakness involving his forehead. He also has vertigo and hearing loss on the same side. What is the SINGLE most likely diagnosis?', 'Ramsay Hunt syndrome is reactivation of varicella-zoster virus in the geniculate ganglion. It causes ear pain, a vesicular rash in the ear canal or pinna (or palate), lower motor neurone facial palsy, and sometimes vertigo and sensorineural hearing loss (VIII involvement). Treat with oral aciclovir/valaciclovir and prednisolone, ideally within 72 hours. Protect the eye. Recovery is less complete than in Bell''s palsy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('050b64f2-3d4d-5a0c-b7c4-b58d15ca5f57', 'b0617719-e263-5d6a-8503-978ba55b2e15', 'A', 'Acoustic neuroma', false, 0),
  ('04070aee-bd7b-5e10-92bc-87a1236c2c4a', 'b0617719-e263-5d6a-8503-978ba55b2e15', 'B', 'Ramsay Hunt syndrome (herpes zoster oticus)', true, 1),
  ('2ebc06cf-3691-5e73-bac1-de6606cbc525', 'b0617719-e263-5d6a-8503-978ba55b2e15', 'C', 'Cholesteatoma', false, 2),
  ('00c677e4-ab52-563e-aaf8-dd1e0cf5a1db', 'b0617719-e263-5d6a-8503-978ba55b2e15', 'D', 'Bell''s palsy', false, 3),
  ('421d63f6-f0dc-5a98-b26d-40c7d8edfe85', 'b0617719-e263-5d6a-8503-978ba55b2e15', 'E', 'Acute otitis externa', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c5f56015-2906-5f12-8073-759b95090d52', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 4 month old baby has had a cough and coryza for 3 days. He now has a respiratory rate of 62/min, subcostal recession, widespread fine crackles and wheeze, and is taking 40% of his usual feeds. His SpO2 is 90% on air. What is the SINGLE most appropriate management?', 'This is bronchiolitis (most often RSV) in an infant. NICE NG9 advises admission for apnoea, persistent SpO2 under 92% on air, oral intake under 50-75% of normal, or severe respiratory distress (grunting, marked recession, RR over 70). Treatment is supportive: oxygen, NG or IV fluids, and nasal suction if needed. Bronchodilators, steroids, antibiotics and physiotherapy are not recommended. A long-acting RSV monoclonal antibody (nirsevimab) and maternal RSV vaccination are now used for prevention.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6ed8fdd0-658f-5038-9fe5-22c21914c2cb', 'c5f56015-2906-5f12-8073-759b95090d52', 'A', 'Admit for supportive care: supplemental oxygen and nasogastric or IV fluids', true, 0),
  ('265dc41a-f095-5734-9294-9d0c34aebc2a', 'c5f56015-2906-5f12-8073-759b95090d52', 'B', 'Chest physiotherapy at home', false, 1),
  ('3dcb81ad-7ef6-5bc1-93cd-1688eee732f1', 'c5f56015-2906-5f12-8073-759b95090d52', 'C', 'Oral prednisolone', false, 2),
  ('18a9327a-a81f-55a9-89df-b6e727fe0d31', 'c5f56015-2906-5f12-8073-759b95090d52', 'D', 'Nebulised salbutamol and discharge', false, 3),
  ('d963a2a0-270e-5870-a5e4-78c0717fb51e', 'c5f56015-2906-5f12-8073-759b95090d52', 'E', 'Oral amoxicillin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e3707155-f791-5065-b4a8-c44b061136e4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 28 year old woman gave birth 8 days ago. She has rapidly developed confusion, insomnia, agitation, fluctuating mood and a belief that her baby has been swapped. She has a history of bipolar disorder. What is the SINGLE most appropriate management?', 'Postpartum (puerperal) psychosis is a psychiatric emergency, usually starting in the first 2 weeks after birth. It is strongly linked to bipolar disorder and causes rapid onset of mania, psychosis, confusion and a risk to mother and baby. Arrange urgent assessment and admission to a mother and baby unit, and treat with antipsychotics, mood stabilisers or ECT. ''Baby blues'' peaks at days 3-5, is mild, and resolves within 2 weeks.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6dc91f38-3adf-5e0b-8686-35446bd4d666', 'e3707155-f791-5065-b4a8-c44b061136e4', 'A', 'Advise her to stop breastfeeding only', false, 0),
  ('8da91129-c8b2-5e8b-a7b6-972e20afe706', 'e3707155-f791-5065-b4a8-c44b061136e4', 'B', 'Reassure that this is ''baby blues'' and review in 2 weeks', false, 1),
  ('c1482594-ee1b-50dd-9dca-3ab1e962752a', 'e3707155-f791-5065-b4a8-c44b061136e4', 'C', 'Start an SSRI in primary care and review in 4 weeks', false, 2),
  ('2b486913-28b0-5962-b28c-5b1455f5ce66', 'e3707155-f791-5065-b4a8-c44b061136e4', 'D', 'Refer for routine counselling', false, 3),
  ('371d8ac7-68ea-5c84-b1ed-b30a04980dd6', 'e3707155-f791-5065-b4a8-c44b061136e4', 'E', 'Urgent psychiatric assessment and admission, ideally to a mother and baby unit', true, 4);
